/* D04：温度信号编解码。自定义教学协议，不连接CAN设备。
 * 前2字节：16位补码整数，每刻度0.1摄氏度；第3字节：模式和雷达位。
 * 第4—8字节保留为0。这里只模拟载荷，不实现CAN驱动或安全控制器。 */
#include <stdio.h>   /* scanf读输入；printf将观察结果打印出来。 */
#include <stdint.h>  /* uint8_t是8位无符号整数；uint32_t是32位无符号整数。 */
#include <stddef.h>  /* size_t用于长度；NULL表示没有可用地址。 */
#include <math.h>    /* isfinite检查有限数；roundf对float四舍五入。 */

/* 函数声明：先告诉编译器名字、参数和返回类型；实现放在main后面。
 * const限制通过该指针写数据；没有const的输出指针允许写回结果。
 * EncodeTemp/DecodeTemp：0成功，-1接口错误，-2数值或协议错误。 */
int EncodeTemp(float temperature, int mode, int radar, int big,
               uint8_t *data, size_t length);
int DecodeTemp(const uint8_t *data, size_t length, int big, float *temperature);
void PrintFrame(const char *name, const uint8_t *data);
void PrintBits(const char *name, uint32_t value, unsigned int width);

int main(void) {
    /* [入口变量] main从这里开始。数组8格，下标0—7；{0}初始化全部格子。
     * main里的对象通常在栈或寄存器中；C标准不强制具体存储位置。 */
    float temperature = 0.0f, decoded = 0.0f;
    int mode = 0, radar = 0, damage = 0, order = 0, length_input = 8;
    uint8_t data[8] = {0};

    /* [读取输入] 输入顺序：温度 模式 雷达 故障 字节顺序 长度。
     * &temperature是变量地址；scanf成功写入6个变量才返回6。
     * order：0双方小端；1双方大端；2发送小端但接收误用大端。 */
    if (scanf("%f %d %d %d %d %d", &temperature, &mode, &radar,
              &damage, &order, &length_input) != 6) {
        printf("status=-3\nvalid=0\n");
        return 0; /* 结束main；业务错误已经打印，进程正常结束。 */
    }
    if (length_input != 8) {
        printf("status=-1\nvalid=0\n");
        return 0; /* 长度错误时不访问任何载荷元素。 */
    }
    if (damage < 0 || damage > 4 || order < 0 || order > 2) {
        printf("status=-2\nvalid=0\n");
        return 0;
    }

    /* [进入编码] 比较表达式order==1得到0或1，作为发送字节顺序。
     * 调用时main暂停；EncodeTemp写data，return状态再赋给status。 */
    int status = EncodeTemp(temperature, mode, radar, order == 1, data, 8);
    printf("status=%d\nvalid=%d\n", status, status == 0);
    if (status != 0) return 0;

    /* [观察发送] 仅为解释重算raw，不把诊断值当正式接收结果。
     * 先用int保存正负刻度，再用65536+负刻度取得16位补码的数值。
     * -12.3×10=-123；65536-123=65413=0xFF85。 */
    int raw_signed = (int)roundf(temperature * 10.0f);
    uint32_t raw_unsigned = (uint32_t)(raw_signed < 0 ? 65536 + raw_signed : raw_signed);
    printf("raw_signed=%d\nraw_unsigned=%u\nlow=%u\nhigh=%u\n",
           raw_signed, (unsigned int)raw_unsigned,
           (unsigned int)(raw_unsigned & 255u), (unsigned int)((raw_unsigned >> 8) & 255u));
    printf("control=%u\n", (unsigned int)data[2]);
    PrintBits("raw_bits", raw_unsigned, 16u);
    PrintBits("control_bits", (uint32_t)data[2], 8u);
    PrintFrame("frame", data);

    /* [故障注入] 顺序：先打印发送帧，再改内存，再解码接收帧。
     * |置1；&加反掩码清0；^翻转。先升到uint32_t，位运算使用无符号数。
     * 3u=00000011；8u=00001000；4u=00000100（这里只画低8位）。 */
    if (damage == 1) data[2] = (uint8_t)((uint32_t)data[2] | 3u);
    if (damage == 2) data[2] = (uint8_t)((uint32_t)data[2] | 8u);
    if (damage == 3) data[0] = (uint8_t)((uint32_t)data[0] ^ 1u);
    if (damage == 4) data[2] = (uint8_t)((uint32_t)data[2] & ~4u);
    PrintFrame("received_frame", data);
    PrintBits("received_bits", (uint32_t)data[2], 8u);
    printf("received_control=%u\nextracted_mode=%u\nextracted_radar=%u\nreserved=%u\n",
           (unsigned int)data[2], (unsigned int)((uint32_t)data[2] & 3u),
           (unsigned int)(((uint32_t)data[2] >> 2) & 1u),
           (unsigned int)((uint32_t)data[2] & 248u));

    /* [回到接收] order!=0表示接收方用大端，order2故意与发送方不一致。
     * unsigned_wrong是故意忽略符号的错误算法，不能当有效温度消费。 */
    uint32_t received_raw;
    if (order != 0) received_raw = ((uint32_t)data[0] << 8) | (uint32_t)data[1];
    else received_raw = (uint32_t)data[0] | ((uint32_t)data[1] << 8);
    printf("received_raw=%u\nunsigned_wrong=%.1f\n",
           (unsigned int)received_raw, (double)((float)received_raw * 0.1f));
    status = DecodeTemp(data, 8, order != 0, &decoded);
    printf("decode_status=%d\ndecode_valid=%d\n", status, status == 0);
    if (status == 0) printf("decoded_temperature=%.1f\n", (double)decoded);
    return 0;
}

int EncodeTemp(float temperature, int mode, int radar, int big,
               uint8_t *data, size_t length) {
    /* [编码校验] 先查地址和长度，再查数值；全通过才开始改data。
     * !表示逻辑取反；||表示任一条件成立就拒绝，不是合并bit的|。 */
    if (data == NULL || length != 8) return -1;
    if (!isfinite(temperature) || temperature < -40.0f || temperature > 125.0f
        || mode < 0 || mode > 2 || radar < 0 || radar > 1
        || big < 0 || big > 1) return -2;

    /* [量化与符号] 本例刻度范围-400—1250，C的int至少能容纳。
     * 65536是2的16次方。负刻度加65536得到0—65535内的16位编码。
     * 不对负数移位；不依赖超范围uint16_t转int16_t的实现行为。 */
    int signed_raw = (int)roundf(temperature * 10.0f);
    uint32_t raw = (uint32_t)(signed_raw < 0 ? 65536 + signed_raw : signed_raw);

    /* [拆字节] &255只保留低8位；>>8让高字节来到最低位置。
     * 小端低字节先写；大端高字节先写。这是协议选择，独立于CPU端序。 */
    uint8_t low = (uint8_t)(raw & 255u);
    uint8_t high = (uint8_t)((raw >> 8) & 255u);
    if (big == 0) { data[0] = low; data[1] = high; }
    else { data[0] = high; data[1] = low; }

    /* [打包控制] mode占bit0—1，radar占bit2；字段不重叠才这样组合。
     * mode2=00000010；radar1<<2=00000100；OR得到00000110，即6。
     * uint8_t运算前通常会整数提升；显式转uint32_t固定无符号移位。 */
    data[2] = (uint8_t)((uint32_t)mode | ((uint32_t)radar << 2));
    for (size_t i = 3; i < 8; i++) data[i] = 0;
    /* 状态经return输出，8字节经data指针写回。 */
    return 0;
}

int DecodeTemp(const uint8_t *data, size_t length, int big, float *temperature) {
    /* [解码校验] 模式3非法；bit3—7和后5字节必须为0。
     * (data[2]&3)提取模式；(data[2]&248)挑出保留位。
     * 雷达0是合法协议值，表示无效；上层是否使用它需要另行判断。 */
    if (data == NULL || temperature == NULL || length != 8) return -1;
    if (big < 0 || big > 1 || ((uint32_t)data[2] & 248u) != 0
        || ((uint32_t)data[2] & 3u) > 2u) return -2;
    for (size_t i = 3; i < 8; i++) if (data[i] != 0) return -2;

    /* [拼回16位] 先转uint32_t再移位。高字节进入bit8—15，低字节留bit0—7。
     * |逐位合并，不进位；0xFF00 | 0x0085 = 0xFF85 = 65413。 */
    uint32_t raw;
    if (big == 0) raw = (uint32_t)data[0] | ((uint32_t)data[1] << 8);
    else raw = ((uint32_t)data[0] << 8) | (uint32_t)data[1];

    /* [还原负刻度] raw的bit15权重32768；它为1时，此补码协议表示负数。
     * raw先转long（至少32位，能装65413），再减65536，避免无符号下溢。
     * 65413-65536=-123；-123×0.1=-12.3摄氏度。 */
    long signed_raw = (long)raw;
    if (raw >= 32768u) signed_raw = signed_raw - 65536L;
    if (signed_raw < -400L || signed_raw > 1250L) return -2;
    *temperature = (float)signed_raw * 0.1f; /* *访问调用者的decoded并写值。 */
    return 0;
}

void PrintFrame(const char *name, const uint8_t *data) {
    /* [打印帧] name是文字如"frame"；%s打印文字；%02X打印至少2位大写十六进制。
     * ?:只选择本次要打印的分隔符。最后i7用换行，前7次用空格。
     * PrintFrame返回void：只打印，不向调用者返回数值。 */
    printf("%s=", name);
    for (size_t i = 0; i < 8; i++) {
        printf("%02X%s", (unsigned int)data[i], i == 7 ? "\n" : " ");
    }
}

void PrintBits(const char *name, uint32_t value, unsigned int width) {
    /* [打印位] 从高位到低位：width8时依次检查bit7、6、5、4、3、2、1、0。
     * i从8减到1；i-1作为位号，避免unsigned i减到0后继续变成大数。
     * (value>>(i-1))&1把这一位移到bit0再取出，只可能0或1。
     * 本程序只用width8/16，不允许任意外部移位量。 */
    printf("%s=", name);
    for (unsigned int i = width; i > 0u; i--) {
        printf("%u", (unsigned int)((value >> (i - 1u)) & 1u));
    }
    printf("\n");
}
